<script setup>
import { useDialogEscape } from '../../lib/dialog.js';
import { ref } from 'vue';import { Head,Link,useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import Errors from '../../Components/Errors.vue';
defineProps({collections:{type:Array,default:()=>[]}});const open=ref(false);const form=useForm({title:'',description:''});
function save(){form.post('/collections',{onSuccess:()=>{open.value=false;form.reset();}});}
useDialogEscape(()=>{open.value=false;});
</script>
<template><Head title="Collections"/><AppLayout title="A place for every idea." subtitle="Gather your words into something worth remembering."><template #actions><button class="button" @click="open=true">+ New collection</button></template><div class="collection-grid"><Link class="collection-card" v-for="(c,i) in collections" :key="c.id" :href="`/collections/${c.id}`"><div class="collection-icon" :class="`tone-${i%3}`">▤</div><span class="tiny-label">{{c.share_uuid?'LINK SHARING ON':'PRIVATE COLLECTION'}}</span><h3>{{c.title}}</h3><p>{{c.description || 'A new world of words.'}}</p><div class="card-bottom"><span>{{c.words_count??c.words?.length??0}} words</span><span>Open →</span></div></Link><button class="collection-card add-card" @click="open=true"><span>＋</span><h3>Start something new.</h3><p>A topic, a lesson, a little curiosity.</p></button></div><div v-if="open" class="modal-backdrop" @click.self="open=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="collection-title"><div class="section-heading"><h2 id="collection-title">New collection</h2><button class="icon-button" aria-label="Close" @click="open=false">×</button></div><form @submit.prevent="save"><Errors :errors="form.errors"/><label>Title<input v-model="form.title" required maxlength="150" autofocus placeholder="e.g. Words for a new adventure"/></label><label>Description<textarea v-model="form.description" maxlength="2000" rows="3" placeholder="What brings these words together?"/></label><p class="muted small">Private by default. You decide when to share.</p><div class="form-actions"><button type="button" class="button secondary" @click="open=false">Cancel</button><button class="button" :disabled="form.processing">Create collection</button></div></form></section></div></AppLayout></template>
